(58, 'Mina de Ouro Assombrada', 'wild_west', 'Desça nas galerias esquecidas da mina de ouro onde brotam espinhos de ferro fundido.', 58000, 0.34, 2.4, ARRAY['spikes', 'moving']::TEXT[]),
(59, 'Cavalgada na Ferrovia dos Despenhadeiros', 'wild_west', '🏃‍♂️ PERCURSO HORIZONTAL! Atravesse a ponte férrea de madeira antes que o trem fantasma chegue!', 59000, 0.36, 2.42, ARRAY['fragile', 'moving']::TEXT[]),
(60, '👑 CHEFÃO 12: Pistoleiro Espectral', 'wild_west', 'DUELO AO MEIO-DIA AOS 60.000m! O xerife fantasma não permite intrusos em seu desfiladeiro!', 60000, 0.26, 2.43, ARRAY['moving', 'fragile', 'spikes']::TEXT[]),
(61, 'Copas das Sequoias Gigantes', 'dinosaur', 'Suba pela vegetação pré-histórica colossal intocada há 150 milhões de anos.', 61000, 0.28, 2.44, ARRAY['springs']::TEXT[]),
(62, 'Pântano dos Fósseis Calcários', 'dinosaur', 'Pise com agilidade extrema nas ossadas ancestrais sobre a lama borbulhante.', 62000, 0.3, 2.46, ARRAY['fragile', 'moving']::TEXT[]),
(63, 'Garganta dos Ninhos de Espinhos', 'dinosaur', 'O ninho das feras está repleto de armadilhas pontiagudas e plataformas instáveis.', 63000, 0.32, 2.47, ARRAY['spikes', 'moving']::TEXT[]),
(64, 'Corrida na Trilha dos Velocirraptores', 'dinosaur', '🏃‍♂️ PERCURSO HORIZONTAL! Corra lateralmente em alta velocidade escapando dos predadores da selva!', 64000, 0.34, 2.48, ARRAY['moving', 'springs']::TEXT[]),
(65, '👑 CHEFÃO 13: T-Rex Titânico Apex', 'dinosaur', 'CONFRONTO PRIMORDIAL AOS 65.000m! Enfrente o rei indiscutível da Era Mesozóica!', 65000, 0.36, 2.49, ARRAY['moving', 'fragile', 'spikes']::TEXT[]),
(66, 'Ágora de Mármore de Atenas', 'olympus', 'A praça central dos filósofos e generais da Grécia Antiga sob a bênção de Atena.', 66000, 0.26, 2.51, ARRAY['moving']::TEXT[]),
(67, 'Colunas Quebradas do Partenon', 'olympus', 'Escale os vestígios do templo sagrado suspenso nos céus da Hélade.', 67000, 0.28, 2.52, ARRAY['fragile', 'springs']::TEXT[]),
(68, 'Forja Divina de Hefesto', 'olympus', 'A forja onde os raios de Zeus são moldados em bronze celestial e fogo eterno.', 68000, 0.3, 2.53, ARRAY['spikes', 'moving']::TEXT[]),
(69, 'Pátio das Bigas do Monte Olimpo', 'olympus', '🏃‍♂️ PERCURSO HORIZONTAL! Acelere pelo hipódromo dos deuses gregos sobre pistas velozes!', 69000, 0.32, 2.55, ARRAY['conveyor', 'moving']::TEXT[]),
(70, '👑 CHEFÃO 14: Minotauro de Bronze', 'olympus', 'DUELO NO LABIRINTO AOS 70.000m! O colosso taurino de bronze forjado quer esmagar seu avanço!', 70000, 0.34, 2.56, ARRAY['moving', 'fragile', 'spikes']::TEXT[]),
(71, 'Mega-Rampa do Half-Pipe Aéreo', 'sports', 'Pratique manobras insanas no maior half-pipe suspenso da galáxia esportiva.', 71000, 0.36, 2.57, ARRAY['springs']::TEXT[]),
(72, 'Circuito da Ginástica Rítmica', 'sports', 'Sincronize seus saltos com o ritmo dos holofotes e conquiste notas perfeitas dos jurados.', 72000, 0.26, 2.59, ARRAY['moving', 'fragile']::TEXT[]),
(73, 'Sprint dos 100 Metros Espaciais', 'sports', '🏃‍♂️ PERCURSO HORIZONTAL! Dispare em arrancada pura na pista sintética com cronômetro em tempo real!', 73000, 0.28, 2.6, ARRAY['conveyor', 'springs']::TEXT[]),
(74, 'Velódromo dos Aros de Fogo', 'sports', 'Pedale nas alturas em uma pista oval futurista projetada para quebrar recordes mundiais.', 74000, 0.3, 2.61, ARRAY['conveyor', 'spikes']::TEXT[]),
(75, '👑 CHEFÃO 15: Gladiador Campeão Titã', 'sports', 'FINAL DO CAMPEONATO AOS 75.000m! Prove ser o atleta absoluto sob o olhar de milhões na torcida!', 75000, 0.32, 2.63, ARRAY['moving', 'fragile', 'springs', 'conveyor']::TEXT[]),
(76, 'Alameda das Frigideiras Ardentes', 'gastronomy', 'Caminhe com cuidado sobre as alças de cobre e chapas quentes da cozinha monumental.', 76000, 0.34, 2.64, ARRAY['moving', 'spikes']::TEXT[]),
(77, 'Caldeirão dos Caldos Efervescentes', 'gastronomy', 'Aproveite a efervescência do caldeirão cósmico para voar mais alto entre conchas douradas.', 77000, 0.36, 2.65, ARRAY['springs', 'fragile']::TEXT[]),
(78, 'Esteira Industrial de Temperos', 'gastronomy', 'Pistas rolantes industriais transportando sacas de açafrão, canela e ervas raras.', 78000, 0.26, 2.66, ARRAY['conveyor', 'moving']::TEXT[]),
(79, 'Esteira dos Confeitos da Grande Cozinha', 'gastronomy', '🏃‍♂️ PERCURSO HORIZONTAL! Corra lateralmente pela bancada do banquete dos deuses gastronômicos!', 79000, 0.28, 2.68, ARRAY['conveyor', 'moving']::TEXT[]),
(80, '👑 CHEFÃO 16: Chef Magmático Vulcânico', 'gastronomy', 'O PRATO PRINCIPAL AOS 80.000m! O mestre cuca do magma quer transformar seu salto em banquete!', 80000, 0.3, 2.69, ARRAY['moving', 'fragile', 'spikes', 'conveyor']::TEXT[]),
(81, 'Hélice Dupla do Código Genético', 'health', 'Suba pela fita de DNA cósmica que guarda as instruções fundamentais da vida eterna.', 81000, 0.32, 2.7, ARRAY['springs']::TEXT[]),
(82, 'Corrente dos Anticorpos Velozes', 'health', 'Desvie dos glóbulos hiperativos que reagem com força a qualquer elemento invasor.', 82000, 0.34, 2.72, ARRAY['moving', 'fragile']::TEXT[]),
(83, 'Ventrículo dos Pulsos Bioelétricos', 'health', 'Sinta a pulsação colossal do núcleo vital e salte exatamente no momento do sístole.', 83000, 0.36, 2.73, ARRAY['spikes', 'springs']::TEXT[]),
(84, 'Artéria Principal da Vida', 'health', '🏃‍♂️ PERCURSO HORIZONTAL! Navegue horizontalmente pela grande artéria em ritmo de alta velocidade!', 84000, 0.26, 2.74, ARRAY['conveyor', 'moving']::TEXT[]),
(85, '👑 CHEFÃO 17: Patógeno Quântico Alfa', 'health', 'QUARANTENA ABSOLUTA AOS 85.000m! Erradique a anomalia microscópica antes que contamine o cosmos!', 85000, 0.28, 2.75, ARRAY['moving', 'fragile', 'spikes', 'springs']::TEXT[]),
(86, 'Camada de Ozônio Ionizada', 'sky_realm', 'Flutue nas franjas do espaço onde o céu se funde com o infinito azul-violeta.', 86000, 0.3, 2.77, ARRAY['springs']::TEXT[]),
(87, 'Nuvem de Granizo Cumulonimbus', 'sky_realm', 'Enfrente o coração de uma tempestade supercelular carregada de raios e saraiva cósmica.', 87000, 0.32, 2.78, ARRAY['wind', 'spikes']::TEXT[]),
(88, 'Cortina Eletromagnética da Aurora', 'sky_realm', 'Dancem sobre as fitas luminescentes da aurora polar que pintam a escuridão estratosférica.', 88000, 0.34, 2.79, ARRAY['moving', 'fragile']::TEXT[]),
(89, 'Corredor das Correntes de Jato', 'sky_realm', '🏃‍♂️ PERCURSO HORIZONTAL! Voe pelas correntes de jato da estratosfera a velocidades supersônicas!', 89000, 0.36, 2.81, ARRAY['wind', 'moving']::TEXT[]),
(90, '👑 CHEFÃO 18: Fênix das Tempestades', 'sky_realm', 'TEMPESTADE ZÊNITE AOS 90.000m! Domine a senhora alada dos ciclones árticos!', 90000, 0.26, 2.82, ARRAY['moving', 'fragile', 'wind', 'spikes']::TEXT[]),
(91, 'Pirâmides Esculpidas dos Andes', 'continents', 'As montanhas sagradas da cordilheira andina guardam segredos astronômicos milenares.', 91000, 0.28, 2.83, ARRAY['moving', 'wind']::TEXT[]),
(92, 'Fiordes Glaciais da Escandinávia', 'continents', 'O reino dos vikings e das geleiras azuis esculpidas pela passagem do tempo.', 92000, 0.3, 2.85, ARRAY['fragile', 'springs']::TEXT[]),
(93, 'Cânions Vermelhos de Uluru', 'continents', 'O coração sagrado do outback australiano pulsando sob a luz dourada do poente.', 93000, 0.32, 2.86, ARRAY['spikes', 'moving']::TEXT[]),
(94, 'Passarela da Grande Muralha Milenar', 'continents', '🏃‍♂️ PERCURSO HORIZONTAL! Salte entre as guaritas imperiais e torres de sinalização de fumaça!', 94000, 0.34, 2.87, ARRAY['moving', 'fragile']::TEXT[]),
(95, '👑 CHEFÃO 19: Esfinge Imperial Global', 'continents', 'O JULGAMENTO DAS CIVILIZAÇÕES AOS 95.000m! Desvende os mistérios da guardiã planetária!', 95000, 0.36, 2.88, ARRAY['moving', 'fragile', 'spikes', 'springs']::TEXT[]),
